(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  [...document.querySelectorAll('.tb-actions button')].find((b) => b.textContent.trim() === '元件库')?.click();
  await sleep(2200);
  return JSON.stringify({ cards: document.querySelectorAll('.lib-card').length, title: document.querySelector('.lib-title')?.textContent });
})()
